            <Ward Code="col:$journal.pat_main.medical_care_info.ward_cd"></Ward>
            <InRoom Code=""></InRoom><!-- 連携対象外 -->
            <Bed Code=""></Bed><!-- 連携対象外 -->
            <AdmissionDate></AdmissionDate><!-- 連携対象外 -->
            <DischargeDate></DischargeDate><!-- 連携対象外 -->
            <AdmissionSnk Code="col:$journal.pat_main.medical_care_info.main_course_cd"></AdmissionSnk>
            <AdmissionDoctor detail="入院主治医,Code"></AdmissionDoctor>
        </AdmissionInfo>
        <InsuranceInfo ctlNo="col:$journal.detail.pat_insurance.ctl_no,const:0">
