            <InsuranceNumber>col:$journal.detail.pat_insurance.insu_info.insu_no</InsuranceNumber>
            <InsuranceDivision>col:$journal.detail.pat_insurance.insu_info.insu_kbn</InsuranceDivision>
            <InsuredSign>col:$journal.detail.pat_insurance.insu_info.insu_pat_mark</InsuredSign>
            <InsuredNumber>col:$journal.detail.pat_insurance.insu_info.insu_pat_no</InsuredNumber>
        </InsuranceInfo>
        <InfectionInfo>
            <!-- 感染症情報 -->
            <Infection detail="感染症情報,Code"></Infection>
        </InfectionInfo>
        <AllergyInfo>
            <!-- アレルギー情報 -->
            <Allergy detail="アレルギー情報,Code"></Allergy>
        </AllergyInfo>
        <DrugAllergyInfo>
            <!-- 薬剤アレルギー情報 -->
            <Drug detail="薬剤アレルギー情報,Code"></Drug>
        </DrugAllergyInfo>
    </PatientData>
</SsiData>', '{"key": {"入院主治医": {"_DEFAULT": "all"}, "患者主治医": {"_DEFAULT": "all"}, "感染症情報": {"_DEFAULT": "all"}, "透析主治医": {"_DEFAULT": "all"}, "透析看護師": {"_DEFAULT": "all"}, "アレルギー情報": {"_DEFAULT": "all"}, "薬剤アレルギー情報": {"_DEFAULT": "all"}}, "dataset": {"sqlGroup1": [{"crud": "S", "kind": "0", "judge": "", "table": "pat_personal_main", "ctl_no": "1", "sqlCode": 1101, "@hospPatId": "$journal.pat_personal_main.hosp_pat_id", "insertResult": "{@fnPatId:'''',@hospPatId:'''',@nkkPatId:'''',@facilityCd:'''',@patLastName:'''',@patFirstName:'''',@patLastNmKana:'''',@patFirstNmKana:'''',@patLastNmAlpha:'''',@patFirstNmAlpha:'''',@patBirthName:'''',@patBirthNmKana:'''',@patBirthNmAlpha:'''',@patBirthday:'''',@patSex:'''',@nationality:'''',@patBloodTypeAbo:'''',@patBloodTypeRh:'''',@patBloodTypeSerovar:'''',@inOutClass:'''',@isDie:'''',@dieCd:'''',@dieDate_Date:'''',@dialDiffComInfoValue:''[]'',@severityCd:'''',@transportCd:'''',@patContactInfoFlg:'''',@patContactInfo.zipCd:'''',@patContactInfo.address:'''',@patContactInfo.tel1:'''',@patContactInfo.tel2:'''',@patContactInfo.fax:'''',@patContactInfo.eMail:'''',@patContactInfo.workName:'''',@patContactInfo.workAddress:'''',@patContactInfo.workTel:'''',@patContactInfo.memo1:'''',@patContactInfo.memo2:'''',@otherContactInfoValue:''[]'',@vendorContactInfoValue:''[]'',@insuranceInfoValue:''[]'',@primaryDiseaseCd:'''',@remoteMonitorService:'''',@remoteMonitorUserId:'''',@remoteMonitorUserPw:''''}", "updateResult": "{@fnPatId:''fn_pat_id'',@hospPatId:''hosp_pat_id'',@nkkPatId:''nkk_pat_id'',@facilityCd:''facility_cd'',@patLastName:''pat_last_name'',@patFirstName:''pat_first_name'',@patLastNmKana:''pat_last_name_kana'',@patFirstNmKana:''pat_first_name_kana'',@patLastNmAlpha:''pat_last_name_alpha'',@patFirstNmAlpha:''pat_first_name_alpha'',@patBirthName:''pat_birth_name'',@patBirthNmKana:''pat_birth_name_kana'',@patBirthNmAlpha:''pat_birth_name_alpha'',@patBirthday:''pat_birthday'',@patSex:''pat_sex'',@nationality:''nationality'',@patBlood